-- Function: public.fn_get_teacher_memories
-- Backup generated on 2026-10-25 20:33:43

CREATE OR REPLACE FUNCTION public.fn_get_teacher_memories(p_tenant_id uuid, p_teacher_id uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)  RETURNS TABLE(id uuid, tenant_id uuid, event_date timestamp with time zone, event_type character varying, title character varying, description text, source_id uuid, source_type character varying, child_id uuid, classroom_id uuid, teacher_id uuid, experience_id uuid)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT * FROM (         SELECT              cs.id, cs.tenant_id, cs.created_at AS event_date,             'Observation'::VARCHAR AS event_type,             'Story'::VARCHAR AS title,             cs.content AS description,             cs.id AS source_id,             'child_stories'::VARCHAR AS source_type,             cs.child_id,             NULL::UUID AS classroom_id,             cs.teacher_id,             es.experience_id         FROM child_stories cs         LEFT JOIN experience_schedules es ON cs.experience_schedule_id = es.id         WHERE cs.tenant_id = p_tenant_id AND cs.teacher_id = p_teacher_id          UNION ALL                  SELECT              je.id, je.tenant_id, je.observation_date AS event_date,             'Observation'::VARCHAR AS event_type,             COALESCE(je.title, 'Journey Entry')::VARCHAR AS title,             je.observation AS description,             je.id AS source_id,             'child_journey_entries'::VARCHAR AS source_type,             je.child_id,             je.classroom_id,             je.teacher_id,             je.experience_id         FROM child_journey_entries je         WHERE je.tenant_id = p_tenant_id AND je.teacher_id = p_teacher_id          UNION ALL          SELECT              s.id, s.tenant_id,             (s.session_date + COALESCE(s.end_time, s.start_time, '00:00:00'::TIME))::TIMESTAMPTZ AS event_date,             'Session'::VARCHAR AS event_type,             'Experience Session'::VARCHAR AS title,             s.actual_notes AS description,             s.id AS source_id,             'experience_sessions'::VARCHAR AS source_type,             NULL::UUID AS child_id,             s.classroom_id,             s.primary_teacher_id AS teacher_id,             s.experience_id         FROM experience_sessions s         WHERE s.tenant_id = p_tenant_id AND s.primary_teacher_id = p_teacher_id          UNION ALL          SELECT              f.id, f.tenant_id,             f.created_at AS event_date,             'Feedback'::VARCHAR AS event_type,             'Teacher Feedback'::VARCHAR AS title,             f.notes AS description,             f.id AS source_id,             'experience_feedbacks'::VARCHAR AS source_type,             NULL::UUID AS child_id,             s.classroom_id,             f.teacher_id,             s.experience_id         FROM experience_feedback f         JOIN experience_schedules s ON f.experience_schedule_id = s.id         WHERE f.tenant_id = p_tenant_id AND f.teacher_id = p_teacher_id     ) AS combined     WHERE (p_start_date IS NULL OR combined.event_date >= p_start_date)       AND (p_end_date IS NULL OR combined.event_date <= p_end_date)     ORDER BY combined.event_date DESC     LIMIT p_limit OFFSET p_offset; END; $function$ ;
